      const p = rest({ lean: lerp(0.03, -0.24, eOut(rev)), leanTop: lerp(0.03, -0.36, eOut(rev)), headTilt: -0.05 * rev, lookX: lerp(-0.18, -0.95, seg(t, 0, 0.1)), lookY: 0.1, browY: -0.6 * rev, browTilt: -0.4 * rev, blink: t > 0.06 && t < 0.1 ? 1 : 0 });
