      while (d < L) { const st = 8 + 7 * H(b, d | 0, 3), ang = a + z * (0.35 + 0.3 * H(b, d | 0, 4)); x += Math.cos(ang) * st; y += Math.sin(ang) * st * 0.8; d += st; z = -z; pts.push([x, Math.min(y, 34)]); }
      out.push(pts);
