      for (let i = 1; i < P.length; i++) { const a = P[i - 1], b = P[i], n = Math.max(1, Math.round(Math.hypot(b[0] - a[0], b[1] - a[1]) / 8)); for (let j = i === 1 ? 0 : 1; j <= n; j++) out.push([ox + a[0] + (b[0] - a[0]) * j / n, a[1] + (b[1] - a[1]) * j / n, li]); }
